 using Microsoft.Extensions.ML;

 var builder = WebApplication.CreateBuilder(args);

 // Train model and register pooled prediction engine
 var mlContext = new MLContext(seed: 42);
 var dataPath = Path.Combine(AppContext.BaseDirectory, "Data", "customers.csv");
 var allData = mlContext.Data.LoadFromTextFile<ChurnInput>(dataPath, hasHeader: true, separatorChar: ',');
 var rowCount = (int)allData.GetColumn<float>(nameof(ChurnInput.Age)).LongCount();

 var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(ChurnInput.Region))
     .Append(mlContext.Transforms.Concatenate("Features", nameof(ChurnInput.Age), nameof(ChurnInput.Income), "RegionEncoded", nameof(ChurnInput.PurchaseHistory)))
     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
         labelColumnName: "Label", featureColumnName: "Features"));

 IDataView trainSet;
 if (rowCount >= 20)
 {
     // Use train/test split when there is enough data
     var split = mlContext.Data.TrainTestSplit(allData, testFraction: 0.2);
     trainSet = split.TrainSet;
     var model = pipeline.Fit(trainSet);
     var predictions = model.Transform(split.TestSet);
     var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
     Console.WriteLine($"Model metrics — AUC: {metrics.AreaUnderRocCurve:F4}, Accuracy: {metrics.Accuracy:F4}, F1: {metrics.F1Score:F4}");
 }
 else
 {
     trainSet = allData;
     Console.WriteLine($"Dataset has only {rowCount} rows — training on all data. Add more rows for proper train/test evaluation.");
 }

 var model = pipeline.Fit(trainSet);

 // Save and register the model for thread-safe predictions
 var modelPath = Path.Combine(AppContext.BaseDirectory, "ChurnModel.zip");
 mlContext.Model.Save(model, trainSet.Schema, modelPath);

 builder.Services.AddPredictionEnginePool<ChurnInput, ChurnOutput>()
     .FromFile(modelPath);

 var app = builder.Build();

 app.MapPost("/predict", (PredictionEnginePool<ChurnInput, ChurnOutput> pool, ChurnRequest req) =>
 {
     var input = new ChurnInput
     {
         Age = req.Age,
         Income = req.Income,
         Region = req.Region,
         PurchaseHistory = req.PurchaseHistory
     };
     var result = pool.Predict(input);
     return Results.Ok(new
     {
         WillChurn = result.PredictedLabel,
         Probability = result.Probability
     });
 });

 app.Run();

 // --- Data models ---

 public class ChurnInput
 {
     [LoadColumn(0)] public float Age { get; set; }
     [LoadColumn(1)] public float Income { get; set; }
     [LoadColumn(2)] public string Region { get; set; } = "";
     [LoadColumn(3)] public float PurchaseHistory { get; set; }
     [LoadColumn(4), ColumnName("Label")] public bool Churned { get; set; }
 }

 public class ChurnOutput
 {
     [ColumnName("PredictedLabel")] public bool PredictedLabel { get; set; }
     public float Probability { get; set; }
 }

 public record ChurnRequest(float Age, float Income, string Region, float PurchaseHistory);

